```c
#include <stdio.h>
#include <math.h>

#define MAX 100                 /* size of the array, as required */

int tab[MAX + 1];               /* tab[k] holds the number k; tab[0] is not used */

/* Fills the array tab with the numbers from 1 to n (position k holds k) */
void initialise(int tab[], int n)
{
