{
    int k;

    if (x < 2)
        return 0;
    for (k = 2; k < x; k++)
        if (tab[k] != 0 && x % tab[k] == 0)
            return 0;           /* a non-zero divisor was found */
    return 1;
}

/* Sets to zero all the multiples of y in tab (up to position n), except y itself */
void setzero(int tab[], int n, int y)
{
    int k;

    for (k = 2 * y; k <= n; k += y)
        tab[k] = 0;
}

/* Displays the non-zero elements of tab up to position n, ten per line */
void doDisplay(int tab[], int n)
{
    int i, count = 0;

    for (i = 1; i <= n; i++)
        if (tab[i] != 0)
        {
            printf("%4d", tab[i]);
            count++;
            if (count % 10 == 0)
                printf("\n");
        }
    if (count % 10 != 0)
        printf("\n");
    printf("Number of primes found: %d\n", count);
}

int main(void)
{
    int n, rootN, p;

    do
    {
        printf("Enter N (2 to %d): ", MAX);
        if (scanf("%d", &n) != 1)
            return 1;           /* not a number: stop */
    } while (n < 2 || n > MAX);

    initialise(tab, n);         /* step 2: fill the array with 1..N */
    tab[1] = 0;                 /* step 3: 1 is not prime */
    rootN = (int) ceil(sqrt((double) n));   /* square root of N, rounded up */

    for (p = 2; p <= rootN; p++)
        if (verifyprime(p))     /* p is the next prime number */
            setzero(tab, n, p); /* step 4: set its multiples to zero */

    printf("Prime numbers between 1 and %d:\n", n);
    doDisplay(tab, n);          /* step 6 */
    return 0;
}
```

Compilation and run (with a C compiler such as gcc): `gcc -std=c11 -Wall -o primes primes.c -lm`, then `./primes`.

